  stops = {
    {kind="boss", floor=1029981, x=0.5469, y=0.3953, name="Saltspine", nameDE="Salzrücken", nameFR="Seléchine", nameES="Espinasal", namePT="Salespino", nameRU="Солеспин", nameKO="소금가시", nameCN="盐脊", nameTW="鹽脊", encounters={3480}, note="Patrols the lake (Lost Marsh) below the entrance; pull him to a cleared, dry spot", noteDE="Läuft über den See (Verlorener Marsch) unterhalb des Eingangs; an eine freigeräumte, trockene Stelle ziehen", noteFR="Patrouille sur le lac (Marais Perdu) en contrebas de l'entrée ; attirez-le sur un endroit sec déjà nettoyé", noteES="Patrulla el lago (Marjal Perdido) debajo de la entrada; atráelo a un punto seco y ya despejado", notePT="Patrulha o lago (Charco Perdido) abaixo da entrada; puxe-o para um local já limpo e seco", noteRU="Патрулирует озеро (Забытая топь) ниже входа; отведите его на зачищенное сухое место", noteKO="입구 아래 호수(잃어버린 늪)를 순찰; 정리된 마른 곳으로 끌어내세요", noteCN="在入口下方的湖（失落沼泽）中巡逻；把他拉到一个已清理过的干燥地点", noteTW="在入口下方的湖（迷失沼澤）巡邏；把他拉到已清空的乾燥地點"},
    {kind="boss", floor=1029981, x=0.3174, y=0.4714, name="Shadetooth", nameDE="Schemenzahn", nameFR="Dent-Sombre", nameES="Sombradiente", namePT="Caninumbra", nameRU="Тенезуб", nameKO="그늘이빨", nameCN="暗齿", nameTW="蔭牙", encounters={3481}, note="In Stalker's Thicket past the crocodile den; clear the stealthed raptors in the grass first, his roar fears players into them; keep him out of the water (reset)", noteDE="Im Pirscherdickicht hinter der Krokodilhöhle; erst die getarnten Raptoren im Gras töten, seine Furcht treibt sonst Spieler hinein; nicht ins Wasser ziehen (setzt zurück)", noteFR="Dans le Fourré du Traqueur, après l'antre des crocodiles ; tuez d'abord les raptors camouflés dans l'herbe, sa peur y envoie les joueurs ; gardez-le hors de l'eau (réinitialisation)", noteES="En la Fronda del Acechador, pasada la guarida de cocodrilos; mata antes a los raptores en sigilo de la hierba, su rugido hace huir a los jugadores hacia ellos; no lo lleves al agua (se reinicia)", notePT="No Matagal do Espreitador, após o covil dos crocodilos; mate antes os raptores furtivos na grama, o rugido dele faz jogadores fugirem até eles; não o leve à água (reinicia)", noteRU="В Чаще ловчего за логовом крокодилов; сначала убейте невидимых ящеров в траве, от его рыка игроки в страхе бегут к ним; не уводите его в воду (он сбросится)", noteKO="악어 소굴 너머 추적자의 숲; 먼저 풀숲에 은신한 랩터를 처치하세요, 그의 포효가 플레이어를 공포에 빠뜨려 랩터 쪽으로 몰아갑니다; 물속으로 끌고 가지 마세요 (초기화)", noteCN="在鳄鱼巢穴后面的潜伏者丛林；先清掉草丛中潜行的迅猛龙，他的咆哮会让玩家恐惧并跑进它们中间；不要把他拉进水里（会重置）", noteTW="在潛獵者灌木林，經過鱷魚巢穴後；先清掉草叢中潛行的迅猛龍，他的咆哮會恐懼玩家，讓他們逃進迅猛龍之中；別讓他進入水中（會重置）"},
    {kind="optional", floor=1029981, x=0.0811, y=0.3734, name="Highland Horror", nameDE="Hochlandschrecken", nameFR="Horreur des hautes-terres", nameES="Horror de las Tierras Altas", namePT="Horror do Planalto", nameRU="Ужас нагорья", nameKO="고원 공포", nameCN="高地恐魔", nameTW="高地之懼", encounters={3644}, note="Optional, only needed for an Alliance quest (no loot): north of the Lost Dig Site", noteDE="Optional, nur für eine Allianz-Quest nötig (keine Beute): nördlich der Vergessenen Ausgrabungsstätte", noteFR="Facultatif, seulement pour une quête de l'Alliance (pas de butin) : au nord du Site de fouilles perdu", noteES="Opcional, solo necesario para una misión de la Alianza (sin botín): al norte de la Excavación Olvidada", notePT="Opcional, só necessário para uma missão da Aliança (sem saque): ao norte do Sítio de Escavação Perdido", noteRU="Необязательно, нужен только для задания Альянса (без добычи): к северу от Забытых раскопок", noteKO="선택, 얼라이언스 퀘스트에만 필요 (전리품 없음): 잃어버린 발굴 현장 북쪽", noteCN="可选，只有一个联盟任务需要（没有战利品）：在迷失挖掘场北边", noteTW="可選，只有一個聯盟任務才需要（沒有戰利品）：在迷失挖掘場北方"},
    {kind="boss", floor=1029981, x=0.3369, y=0.6589, name="Relic Guardian", nameDE="Reliktwächter", nameFR="Gardien des reliques", nameES="Guardián de reliquias", namePT="Guardião da Relíquia", nameRU="Страж реликвий", nameKO="유물 수호자", nameCN="遗迹守卫者", nameTW="聖物守護者", encounters={3482}, note="Last boss; the Archival Panel to his right starts the fight; his knockback costs the tank threat, so damage dealers wait until the tank has him back", noteDE="Letzter Boss; das Pult rechts von ihm startet den Kampf; sein Rückstoß kostet den Tank Bedrohung, Schaden erst wieder, wenn der Tank ihn zurück hat", noteFR="Dernier boss ; l'Archival Panel à sa droite lance le combat ; sa projection coûte de la menace au tank, les DPS attendent donc que le tank l'ait repris", noteES="Último jefe; el Archival Panel a su derecha inicia el combate; su empujón le quita amenaza al tanque, así que los DPS esperan a que el tanque lo recupere", notePT="Último chefe; o Archival Panel à direita dele inicia a luta; o empurrão dele faz o tanque perder ameaça, então quem causa dano espera até o tanque retomá-lo", noteRU="Последний босс; бой начинается с Archival Panel справа от него; из-за его отбрасывания танк теряет угрозу, поэтому бойцы ждут, пока танк снова не перехватит его", noteKO="마지막 우두머리; 그의 오른쪽에 있는 Archival Panel로 전투가 시작됩니다; 그의 밀쳐내기로 탱커의 어그로가 줄어드니, 탱커가 다시 잡을 때까지 딜러는 기다리세요", noteCN="最后一个首领；他右边的Archival Panel会开启战斗；他的击退会让坦克损失仇恨，所以输出要等坦克重新拉住他再打", noteTW="最終首領；啟動他右邊的 Archival Panel 即開始戰鬥；他的擊退會讓坦克失去仇恨，所以輸出要等坦克重新拉住他再攻擊"},
  },
  notes = {
  },
  links = {
  },
}

