  stops = {
    {kind="boss", floor=1030391, x=0.2939, y=0.7365, name="Slavecrusher Grox", nameDE="Sklavenbrecher Grox", nameFR="Brise-esclave Grox", nameES="Machacaesclavos Grox", namePT="Grox Esmaga-escravos", nameRU="Рабомучитель Грокс", nameKO="노예파괴자 그록스", nameCN="碎奴者格罗克斯", nameTW="碎奴者古羅斯", encounters={3450}, note="First boss, wanders east of the entrance between the clearing and the side road above it, sometimes right at the first fork", noteDE="Erster Boss, wandert östlich vom Eingang zwischen der Lichtung und dem Seitenweg darüber, manchmal direkt an der ersten Abzweigung", noteFR="Premier boss, erre à l'est de l'entrée entre la clairière et le chemin latéral au-dessus, parfois juste au premier embranchement", noteES="Primer jefe, deambula al este de la entrada entre el claro y el camino lateral de arriba, a veces justo en la primera bifurcación", notePT="Primeiro chefe, vaga a leste da entrada entre a clareira e o caminho lateral acima dela, às vezes bem na primeira bifurcação", noteRU="Первый босс, бродит к востоку от входа между поляной и боковой дорогой над ней, иногда прямо у первой развилки", noteKO="첫 번째 우두머리, 입구 동쪽의 공터와 그 위쪽 샛길 사이를 돌아다님, 가끔 첫 갈림길 바로 앞에 있음", noteCN="第一个首领，在入口以东的空地和它上方的岔路之间游荡，有时就在第一个岔路口", noteTW="第一個首領，在入口以東的空地和它上方的岔路之間遊蕩，有時就在第一個岔路口"},
    {kind="boss", floor=1030391, x=0.415, y=0.716, name="Twilight Commander Zarmok", nameDE="Twilight-Kommandant Zarmok", nameFR="Commandant du Crépuscule Zarmok", nameES="Comandante Crepuscular Zarmok", namePT="Comandante do Crepúsculo Zarmok", nameRU="Сумеречный командир Зармок", nameKO="황혼의 사령관 자르모크", nameCN="暮光指挥官扎尔莫克", nameTW="暮光指揮官札莫克", encounters={3452}, note="Patrols among the buildings in the middle, his death opens the large gate; his charge hits the farthest player, so stand close together", noteDE="Läuft zwischen den Gebäuden in der Mitte umher, sein Tod öffnet das große Tor; sein Ansturm trifft den entferntesten Spieler, also dicht beieinander stehen", noteFR="Patrouille entre les bâtiments du centre, sa mort ouvre la grande porte ; sa charge frappe le joueur le plus éloigné, restez donc groupés", noteES="Patrulla entre los edificios del centro, su muerte abre el gran portón; su carga golpea al jugador más lejano, así que mantén al grupo bien agrupado", notePT="Patrulha entre os edifícios no centro, a morte dele abre o grande portão; a investida dele atinge o jogador mais distante, então fiquem juntos", noteRU="Патрулирует среди зданий в центре, его смерть открывает большие ворота; его рывок бьет по самому дальнему игроку, поэтому держитесь вместе", noteKO="가운데 건물들 사이를 순찰, 그가 죽으면 큰 관문이 열립니다; 돌진이 가장 먼 플레이어에게 맞으니 서로 붙어 서세요", noteCN="在中间的建筑之间巡逻，他死后大门会打开；他的冲锋会命中距离最远的玩家，所以要靠拢站位", noteTW="在中央的建築之間巡邏，他死後會打開大門；他的衝鋒會擊中最遠的玩家，所以要靠在一起站"},
    {kind="optional", floor=1030391, x=0.6299, y=0.5534, name="Handler Ashka", nameDE="Tierführerin Ashka", nameFR="Dresseuse Ashka", nameES="Cuidadora Ashka", namePT="Domadora Ashka", nameRU="Укротительница Ашка", nameKO="조련사 아쉬카", nameCN="驯兽师阿什卡", nameTW="管理員艾絲卡", encounters={3453}, note="Called War Handler Ashka in the game; optional, in the yard in the east with two wolves, many groups skip her; kill the wolves first", noteDE="Heißt im Spiel „Kriegswärterin Ashka“; optional, im Hof im Osten mit zwei Wölfen, viele Gruppen lassen sie aus; zuerst die Wölfe töten", noteFR="Appelée Marchande de guerre Ashka dans le jeu ; facultative, dans la cour à l'est avec deux loups, beaucoup de groupes la passent ; tuez d'abord les loups", noteES="En el juego se llama Cuidadora de guerra Ashka; opcional, en el patio del este con dos lobos, muchos grupos se la saltan; mata primero a los lobos", notePT="No jogo se chama Domadora de Guerra Ashka; opcional, no pátio a leste com dois lobos, muitos grupos a pulam; mate os lobos primeiro", noteRU="В игре называется «Военачальница Ашка»; необязательно, во дворе на востоке с двумя волками, многие группы ее пропускают; сначала убейте волков", noteKO="게임에서는 전투조련사 아쉬카라는 이름입니다; 선택, 동쪽 안뜰에서 늑대 2마리와 함께, 많은 파티가 건너뜁니다; 늑대를 먼저 처치하세요", noteCN="游戏中名为War Handler Ashka；可选，在东边的院子里，带着两只狼，很多队伍会跳过她；先杀狼", noteTW="遊戲中名為「戰爭管理員艾絲卡」；可選，在東邊的庭院，帶著兩隻狼，很多隊伍會跳過她；先殺掉狼"},
    {kind="optional", floor=1030391, x=0.6777, y=0.489, name="Tunk", note="Elite blacksmith right after, in the small forge; drops Krol'dok Moulding (starts a quest for a key)", noteDE="Elite-Schmied gleich danach in der kleinen Schmiede; lässt Krol'dok Moulding fallen (startet eine Quest für einen Schlüssel)", noteFR="Forgeron élite juste après, dans la petite forge ; lâche le Moulage krol’dok (lance une quête pour une clé)", noteES="Herrero élite justo después, en la pequeña forja; suelta la Moldura Krol'Dok (inicia una misión para una llave)", notePT="Ferreiro de elite logo depois, na pequena forja; deixa cair a Moldura Krol'dok (inicia uma missão para obter uma chave)", noteRU="Элитный кузнец сразу после, в маленькой кузнице; с него падает Крол'докская форма (начинает задание на ключ)", noteKO="바로 뒤 작은 대장간의 정예 대장장이; 크롤도크 거푸집을 떨어뜨립니다 (열쇠 퀘스트 시작)", noteCN="紧接着在小铁匠铺里有一名精英铁匠；掉落克罗多克铸件（开启一个获取钥匙的任务）", noteTW="緊接著在小鍛造坊裡的精英鍛造師；掉落克羅多克模具（開始一個取得鑰匙的任務）"},
    {kind="optional", floor=1030391, x=0.4277, y=0.4949, name="Zalfan Moonshadow", note="Quest target, not a boss: in the yard in the north, on the way from the bridge tower to Nar'gurk", noteDE="Questziel, kein Boss: im Hof im Norden, auf dem Weg vom Brückenturm zu Nar'gurk", noteFR="Cible de quête, pas un boss : dans la cour au nord, sur le chemin entre la tour du pont et Nar’gurk", noteES="Objetivo de misión, no es un jefe: en el patio del norte, de camino desde la torre del puente hasta Nar'gurk", notePT="Alvo de missão, não é chefe: no pátio ao norte, no caminho da torre da ponte até Nar'gurk", noteRU="Цель задания, не босс: во дворе на севере, по пути от башни на мосту к Нар'гурку", noteKO="퀘스트 대상, 우두머리 아님: 북쪽 안뜰, 다리 탑에서 나르구르크로 가는 길", noteCN="任务目标，不是首领：在北边的院子里，在从桥塔前往纳古克的路上", noteTW="任務目標，不是首領：在北邊的庭院，從橋塔前往納古克的路上"},
    {kind="boss", floor=1030391, x=0.374, y=0.5725, name="Nar'gurk", nameFR="Nar’gurk", nameRU="Нар'гурк", nameKO="나르구르크", nameCN="纳古克", nameTW="納古克", encounters={3449}, note="At the ritual circle on the stone walkway, with several casters; interrupt their casts; he mind-controls a player: damage them to half health to free them", noteDE="Am Ritualkreis auf dem Steinweg, mit mehreren Zauberern; Zauber unterbrechen; er übernimmt einen Spieler: diesen auf halbe Gesundheit bringen, dann ist er frei", noteFR="Au cercle rituel sur la passerelle de pierre, avec plusieurs lanceurs de sorts ; interrompez-les ; il contrôle un joueur : frappez-le jusqu'à la moitié de sa vie pour le libérer", noteES="En el círculo ritual del camino de piedra, con varios lanzadores de hechizos; interrumpe sus conjuros; controla la mente de un jugador: hazle daño hasta dejarlo a media salud para liberarlo", notePT="Junto ao círculo ritual no caminho de pedra, com vários conjuradores; interrompa os feitiços deles; ele domina a mente de um jogador: reduza a vida dele à metade para libertá-lo", noteRU="У ритуального круга на каменном переходе, с несколькими заклинателями; прерывайте их заклинания; он подчиняет себе игрока: снизьте его здоровье до половины, чтобы освободить", noteKO="돌 통로 위의 의식진, 시전자 여럿과 함께; 시전을 차단하세요; 그는 플레이어 한 명을 정신 지배합니다: 그 플레이어의 생명력을 절반까지 깎아 풀어 주세요", noteCN="在石头步道上的仪式法阵处，有数名施法者；打断他们的施法；他会精神控制一名玩家：把该玩家打到一半生命值即可解救", noteTW="在石砌步道上的儀式法陣，有數名施法者；打斷他們的施法；他會心靈控制一名玩家：把該玩家打到一半生命值即可解救他"},
    {kind="optional", floor=1030391, x=0.6113, y=0.4495, name="Bossman Toof", note="North-east end of the large wooden bridge: two centurions at the bridge start his fight; kill his shamans first; not in the game's boss list, tick him off by hand", noteDE="Nordostende der großen Holzbrücke: zwei Zenturionen an der Brücke starten seinen Kampf; zuerst seine Schamanen töten; nicht in der Bossliste des Spiels, von Hand abhaken", noteFR="Extrémité nord-est du grand pont en bois : deux centurions près du pont lancent son combat ; tuez d'abord ses chamans ; absent de la liste des boss du jeu, cochez-le à la main", noteES="Extremo noreste del gran puente de madera: dos centuriones en el puente inician su combate; mata primero a sus chamanes; no está en la lista de jefes del juego, márcalo a mano", notePT="Ponta nordeste da grande ponte de madeira: dois centuriões na ponte iniciam a luta dele; mate primeiro os xamãs dele; não está na lista de chefes do jogo, marque-o manualmente", noteRU="У северо-восточного конца большого деревянного моста: бой с ним начинают два центуриона у моста; сначала убейте его шаманов; его нет в списке боссов игры, отметьте его вручную", noteKO="큰 나무다리 북동쪽 끝: 다리의 백부장 2명이 그와의 전투를 시작시킵니다; 그의 주술사들을 먼저 처치하세요; 게임의 우두머리 목록에 없으니 직접 체크하세요", noteCN="大木桥的东北端：桥边的两个百夫长会开启他的战斗；先杀他的萨满祭司；不在游戏的首领列表中，请手动勾选", noteTW="大木橋的東北端：橋頭的兩名百夫長會觸發他的戰鬥；先殺他的薩滿；不在遊戲的首領列表中，請手動勾選"},
    {kind="boss", floor=1030391, x=0.6797, y=0.1523, name="Overseer Mugg", nameDE="Aufseher Mugg", nameFR="Suzerain Mugg", nameES="Sobrestante Mugg", namePT="Feitor Mugg", nameRU="Надзиратель Магг", nameKO="감독관 머그", nameCN="监工莫格", nameTW="監督者馬戈", encounters={3451}, note="Called Overlord Mugg in the game; last boss, in the large hall at the top; kill his two centurions first; he leaps at three players, so spread out", noteDE="Heißt im Spiel „Oberanführer Mugg“; letzter Boss, in der großen Halle ganz oben; zuerst seine zwei Zenturionen töten; er springt zu drei Spielern, also verteilt stehen", noteFR="Appelé Suzerain Mugg dans le jeu ; dernier boss, dans la grande salle tout en haut ; tuez d'abord ses deux centurions ; il bondit sur trois joueurs, dispersez-vous donc", noteES="En el juego se llama Señor supremo Mugg; último jefe, en la gran sala de arriba; mata primero a sus dos centuriones; salta sobre tres jugadores, así que mantén al grupo disperso", notePT="No jogo se chama Lorde Supremo Mugg; último chefe, no grande salão no alto; mate primeiro os dois centuriões dele; ele salta sobre três jogadores, então espalhem-se", noteRU="В игре называется «Властитель Магг»; последний босс, в большом зале наверху; сначала убейте двух его центурионов; он прыгает на трех игроков, поэтому разойдитесь", noteKO="게임에서는 대군주 머그라는 이름입니다; 마지막 우두머리, 맨 위의 큰 홀; 그의 백부장 2명을 먼저 처치하세요; 플레이어 3명에게 뛰어드니 흩어지세요", noteCN="游戏中名为Overlord Mugg；最后一个首领，在最上方的大厅里；先杀他的两个百夫长；他会跃向三名玩家，所以要分散站位", noteTW="遊戲中名為「霸主馬戈」；最終首領，位於最上層的大廳；先殺他的兩名百夫長；他會跳向三名玩家，所以要分散站位"},
  },
  notes = {
    {floor=1030391, x=0.5645, y=0.4832, text="Tower in the middle of the bridge: first north-west to Nar'gurk, later back from the south-west and across the bridge to the north-east", textDE="Turm in der Brückenmitte: erst nach Nordwesten zu Nar'gurk, später von Südwesten zurück und über die Brücke nach Nordosten", textFR="Tour au milieu du pont : d'abord au nord-ouest vers Nar’gurk, plus tard retour par le sud-ouest et à travers le pont vers le nord-est", textES="Torre en medio del puente: primero al noroeste hasta Nar'gurk, después de vuelta desde el suroeste y cruzando el puente hacia el noreste", textPT="Torre no meio da ponte: primeiro para noroeste até Nar'gurk, depois de volta pelo sudoeste e pela ponte até o nordeste", textRU="Башня посреди моста: сначала на северо-запад к Нар'гурку, позже обратно с юго-запада и через мост на северо-восток", textKO="다리 가운데의 탑: 먼저 북서쪽 나르구르크로, 나중에 남서쪽에서 돌아와 다리를 건너 북동쪽으로", textCN="桥中央的塔：先往西北去纳古克，之后从西南返回，再过桥去东北", textTW="橋中央的塔：先往西北到納古克，之後從西南返回並過橋到東北"},
  },
  links = {
  },
}

